def transform(grid):
    """Expand marker strokes between matching opposite edge rails."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    edge_colors = Counter(
        g[r][c]
        for r in range(h)
        for c in range(w)
        if g[r][c] != bg and (r in (0, h - 1) or c in (0, w - 1))
    )
    rail = edge_colors.most_common(1)[0][0]

    # This task places equal-length vertical rails on opposite side edges,
    # with the second rail shifted along the rail direction.
    def runs(coords):
        groups = []
        for x in coords:
            if not groups or x != groups[-1][-1] + 1:
                groups.append([x])
            else:
                groups[-1].append(x)
        return groups

    left = runs([r for r in range(h) if g[r][0] == rail])
    right = runs([r for r in range(h) if g[r][w - 1] == rail])
    if not left or not right:
        return g
    a = max(left, key=len)
    b = max(right, key=len)
    if len(a) != len(b):
        return g

    markers = [(r, c) for r in range(h) for c in range(w)
               if g[r][c] != bg and g[r][c] != rail]
    for r, c in markers:
        # Replace each signal with the 4-colored endpoint.
        signal = g[r][c]
        g[r][c] = 4
        # A marker on the first rail's span projects to the matching row of
        # the opposite rail; fill the connecting stroke.
        if a[0] <= r <= a[-1]:
            rr = b[0] + (r - a[0])
            if 0 <= rr < h:
                for x in range(1, w - 1):
                    if g[rr][x] == bg:
                        g[rr][x] = signal
            # Extend the local ray from the marker to its aligned rail.
            for x in range(1, c):
                if g[r][x] == bg:
                    g[r][x] = signal
        elif b[0] <= r <= b[-1]:
            rr = a[0] + (r - b[0])
            if 0 <= rr < h:
                for x in range(1, w - 1):
                    if g[rr][x] == bg:
                        g[rr][x] = signal
            for x in range(c + 1, w - 1):
                if g[r][x] == bg:
                    g[r][x] = signal
    return g
