def _runs(indices):
    out = []
    for x in indices:
        if not out or x != out[-1][-1] + 1:
            out.append([x])
        else:
            out[-1].append(x)
    return out


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    freq = Counter(v for row in g for v in row)
    bg = freq.most_common(1)[0][0]

    # Find the repeated color rails on opposite borders. The paired runs have
    # equal length; they may be offset along the border.
    choices = []
    for axis in (0, 1):  # axis=0: top/bottom rails; axis=1: left/right rails
        lim = w if axis == 0 else h
        edge_a = [g[0][i] if axis == 0 else g[i][0] for i in range(lim)]
        edge_b = [g[h - 1][i] if axis == 0 else g[i][w - 1] for i in range(lim)]
        for color in set(edge_a + edge_b) - {bg}:
            a = _runs([i for i, v in enumerate(edge_a) if v == color])
            b = _runs([i for i, v in enumerate(edge_b) if v == color])
            for x in a:
                for y in b:
                    if len(x) == len(y):
                        choices.append((len(x), color, axis, x, y))
    if not choices:
        return g
    _, rail, axis, ra, rb = max(choices, key=lambda z: (z[0], z[1] != bg))

    # For each isolated signal on the span of one rail, draw a ray to that
    # rail, and project the same offset across the opposite edge's open field.
    signals = [(r, c, g[r][c]) for r in range(h) for c in range(w)
               if g[r][c] != bg and g[r][c] != rail]
    for r, c, color in signals:
        q = c if axis == 0 else r
        own = other = None
        if ra[0] <= q <= ra[-1]:
            own, other = ra, rb
            toward = -1 if axis == 0 else -1
        elif rb[0] <= q <= rb[-1]:
            own, other = rb, ra
            toward = 1
        else:
            continue
        offset = q - own[0]
        mapped = other[0] + offset
        # Signal ray to the rail on its own side.
        if axis == 0:
            edge_row = 0 if own is ra else h - 1
            step = 1 if edge_row < r else -1
            rr = r + step
            while 0 <= rr < h and rr != edge_row:
                if g[rr][c] == bg:
                    g[rr][c] = color
                rr += step
        else:
            edge_col = 0 if own is ra else w - 1
            step = 1 if edge_col < c else -1
            cc = c + step
            while 0 <= cc < w and cc != edge_col:
                if g[r][cc] == bg:
                    g[r][cc] = color
                cc += step
        g[r][c] = 4

        # Project from the other rail along the perpendicular line to the far
        # border (the opposite rail occupies a shifted position there).
        if axis == 0:
            edge_row = 0 if other is ra else h - 1
            step = 1 if edge_row == 0 else -1
            rr = edge_row + step
            while 0 <= rr < h and rr != (h - 1 if edge_row == 0 else 0):
                if g[rr][mapped] == bg:
                    g[rr][mapped] = color
                rr += step
        else:
            edge_col = 0 if other is ra else w - 1
            step = 1 if edge_col == 0 else -1
            cc = edge_col + step
            while 0 <= cc < w and cc != (w - 1 if edge_col == 0 else 0):
                if g[mapped][cc] == bg:
                    g[mapped][cc] = color
                cc += step
    return g
